[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellSource — Expert Health Guidance You Can Trust</title>
<meta name="description" content="WellSource delivers medically reviewed health and wellness content, tools, and resources to empower informed health decisions.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/remixicon@4.6.0/fonts/remixicon.css" rel="stylesheet">
<style>
:root {
  --teal: #02838D;
  --teal-dark: #016974;
  --teal-light: #E6F3F5;
  --teal-bg: #F2F8F9;
  --charcoal: #231F20;
  --white: #FFFFFF;
  --coral: #E87040;
  --coral-hover: #D15E32;
  --amber: #F5A623;
  --gray-50: #FAFAFA;
  --gray-100: #F5F5F5;
  --gray-200: #E8E8E8;
  --gray-300: #D4D4D4;
  --gray-400: #A0A0A0;
  --gray-500: #6B6B6B;
  --gray-600: #4A4A4A;
  --gray-700: #333333;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.10);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --max-width: 1280px;
  --transition: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--charcoal);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ── Top Bar ── */
.top-bar {
  background: var(--charcoal);
  color: var(--white);
  font-size: 13px;
  padding: 8px 0;
  overflow: hidden;
}
.top-bar .container { display: flex; align-items: center; justify-content: space-between; }
.top-bar a { color: var(--gray-300); transition: color var(--transition); }
.top-bar a:hover { color: var(--white); }
.top-bar-right { display: flex; gap: 20px; align-items: center; }

/* ── Header ── */
.header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.logo {
  font-size: 26px;
  font-weight: 800;
  color: var(--teal);
  letter-spacing: -0.5px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo i { font-size: 28px; color: var(--teal); }
.header-actions { display: flex; align-items: center; gap: 12px; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 22px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-outline {
  border: 1.5px solid var(--teal);
  color: var(--teal);
  background: var(--white);
}
.btn-outline:hover { background: var(--teal-light); }
.btn-primary {
  background: var(--coral);
  color: var(--white);
}
.btn-primary:hover { background: var(--coral-hover); }
.btn-teal {
  background: var(--teal);
  color: var(--white);
}
.btn-teal:hover { background: var(--teal-dark); }
.btn-lg { padding: 13px 28px; font-size: 15px; border-radius: 28px; }

/* ── Navigation ── */
.main-nav { display: flex; gap: 4px; }
.nav-item { position: relative; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: 6px;
  transition: all var(--transition);
}
.nav-link:hover, .nav-link.active { color: var(--teal); background: var(--teal-light); }
.nav-link i { font-size: 16px; transition: transform var(--transition); }

/* ── Mega Menu ── */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 28px 32px;
  min-width: 680px;
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s ease;
  border: 1px solid var(--gray-200);
  z-index: 99;
}
.nav-item:hover .mega-menu { opacity: 1; visibility: visible; transform: translateX(-50%) translateY(4px); }
.mega-menu-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px 24px; }
.mega-menu-cols.cols-2 { grid-template-columns: repeat(2, 1fr); }
.mega-menu-cols.cols-4 { grid-template-columns: repeat(4, 1fr); }
.mega-menu a {
  display: block;
  padding: 7px 12px;
  font-size: 13px;
  color: var(--gray-600);
  border-radius: 6px;
  transition: all var(--transition);
}
.mega-menu a:hover { background: var(--teal-bg); color: var(--teal); }
.mega-menu-heading {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--gray-400);
  padding: 0 12px;
  margin-bottom: 6px;
}
.mega-menu-highlight {
  grid-column: 1 / -1;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--gray-200);
  display: flex;
  gap: 16px;
}
.mega-menu-highlight a {
  font-weight: 600;
  color: var(--teal);
  padding: 8px 14px;
  background: var(--teal-light);
  border-radius: 8px;
}

/* ── Ticker Bar ── */
.ticker-bar {
  background: var(--teal);
  color: var(--white);
  padding: 10px 0;
  overflow: hidden;
  position: relative;
}
.ticker-track {
  display: flex;
  gap: 60px;
  animation: tickerScroll 20s linear infinite;
  width: max-content;
}
.ticker-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  flex-shrink: 0;
}
.ticker-item i { font-size: 18px; opacity: 0.9; }
.ticker-item .stat { font-weight: 700; }
@keyframes tickerScroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ── Hero ── */
.hero {
  background: linear-gradient(170deg, var(--teal-bg) 0%, var(--white) 100%);
  padding: 64px 0;
}
.hero .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--coral);
  color: var(--white);
  padding: 6px 16px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 20px;
}
.hero-category {
  color: var(--teal);
  font-weight: 700;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 12px;
}
.hero-title {
  font-size: 46px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--charcoal);
  margin-bottom: 16px;
  letter-spacing: -0.5px;
}
.hero-subtitle {
  font-size: 18px;
  color: var(--gray-500);
  margin-bottom: 28px;
  line-height: 1.6;
  max-width: 480px;
}
.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}
.hero-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  box-shadow: var(--shadow-lg);
  text-align: center;
  position: relative;
  max-width: 380px;
}
.hero-card-icon {
  width: 120px;
  height: 120px;
  background: linear-gradient(135deg, var(--teal-light), var(--teal-bg));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
}
.hero-card-icon i { font-size: 60px; color: var(--teal); }
.hero-card .day-badge {
  font-size: 14px;
  font-weight: 700;
  color: var(--coral);
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.hero-card .challenge-label {
  font-size: 18px;
  font-weight: 700;
  color: var(--charcoal);
}
.hero-card .challenge-sub {
  font-size: 13px;
  color: var(--gray-500);
  margin-top: 4px;
}

/* ── Content Grid ── */
.content-section { padding: 56px 0; }
.content-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 48px;
  align-items: start;
}

/* ── Trending Sidebar ── */
.trending-sidebar {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  padding: 24px;
  position: sticky;
  top: 88px;
}
.trending-sidebar h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--charcoal);
}
.trending-list { list-style: none; }
.trending-list li { margin-bottom: 16px; padding-bottom: 16px; border-bottom: 1px solid var(--gray-200); }
.trending-list li:last-child { margin-bottom: 0; padding-bottom: 0; border-bottom: none; }
.trending-category {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--teal);
  margin-bottom: 4px;
}
.trending-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  line-height: 1.4;
  transition: color var(--transition);
}
.trending-title:hover { color: var(--teal); }

/* ── Section Headers ── */
.section-label {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--teal);
  margin-bottom: 8px;
}
.section-title {
  font-size: 32px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 12px;
  letter-spacing: -0.3px;
}
.section-body {
  font-size: 16px;
  color: var(--gray-500);
  max-width: 600px;
  margin-bottom: 32px;
  line-height: 1.6;
}
.section-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}
.view-all {
  font-size: 14px;
  font-weight: 600;
  color: var(--teal);
  display: flex;
  align-items: center;
  gap: 4px;
  transition: color var(--transition);
}
.view-all:hover { color: var(--teal-dark); }

/* ── Newsletter CTA ── */
.newsletter-cta {
  background: var(--teal);
  color: var(--white);
  padding: 56px 0;
  position: relative;
  overflow: hidden;
}
.newsletter-cta::before {
  content: '';
  position: absolute;
  right: -80px;
  top: -40px;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: rgba(255,255,255,0.05);
}
.newsletter-cta::after {
  content: '';
  position: absolute;
  left: 10%;
  bottom: -60px;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: rgba(255,255,255,0.04);
}
.newsletter-cta .container { position: relative; z-index: 1; }
.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 48px;
}
.newsletter-cta h3 {
  font-size: 28px;
  font-weight: 800;
  margin-bottom: 8px;
  letter-spacing: -0.3px;
}
.newsletter-cta p {
  font-size: 16px;
  opacity: 0.9;
  max-width: 480px;
  line-height: 1.5;
}
.newsletter-form {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
  background: var(--white);
  padding: 6px;
  border-radius: 32px;
}
.newsletter-form input {
  border: none;
  padding: 12px 20px;
  font-size: 15px;
  width: 280px;
  outline: none;
  border-radius: 26px;
  background: transparent;
}
.newsletter-form input::placeholder { color: var(--gray-400); }
.newsletter-form button {
  background: var(--coral);
  color: var(--white);
  padding: 12px 28px;
  border-radius: 26px;
  font-size: 15px;
  font-weight: 600;
  transition: background var(--transition);
}
.newsletter-form button:hover { background: var(--coral-hover); }
.newsletter-cta .privacy-note {
  font-size: 12px;
  opacity: 0.7;
  margin-top: 12px;
}

/* ── Health Topics Carousel ── */
.carousel-wrapper { position: relative; }
.carousel-viewport { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track {
  display: flex;
  gap: 20px;
  transition: transform 0.4s ease;
}
.topic-card {
  flex: 0 0 calc(16.666% - 17px);
  min-width: 160px;
  text-align: center;
  cursor: pointer;
}
.topic-card-img {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: var(--teal-bg);
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  overflow: hidden;
}
.topic-card:hover .topic-card-img { box-shadow: 0 0 0 4px var(--teal-light), var(--shadow-md); transform: scale(1.05); }
.topic-card-img i { font-size: 40px; color: var(--teal); }
.topic-card-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  line-height: 1.3;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition);
  color: var(--charcoal);
  border: 1px solid var(--gray-200);
}
.carousel-btn:hover { background: var(--teal-light); border-color: var(--teal); }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }
.carousel-prev { left: -48px; }
.carousel-next { right: -48px; }

/* ── Tools Section ── */
.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.tool-hub {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  padding: 32px;
}
.tool-hub-icon {
  width: 52px;
  height: 52px;
  background: var(--teal-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}
.tool-hub-icon i { font-size: 26px; color: var(--teal); }
.tool-hub h4 { font-size: 20px; font-weight: 700; margin-bottom: 8px; }
.tool-hub p { font-size: 14px; color: var(--gray-500); margin-bottom: 20px; line-height: 1.6; }
.tool-items { display: flex; flex-direction: column; gap: 12px; margin-top: 20px; }
.tool-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: var(--white);
  border-radius: var(--radius-md);
  transition: all var(--transition);
  border: 1px solid transparent;
}
.tool-item:hover { border-color: var(--teal-light); box-shadow: var(--shadow-sm); }
.tool-item-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--teal-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.tool-item-icon i { font-size: 20px; color: var(--teal); }
.tool-item-text h5 { font-size: 14px; font-weight: 600; color: var(--charcoal); }
.tool-item-text p { font-size: 12px; color: var(--gray-400); margin: 0; }

/* ── Recommended Reads ── */
.tabs-nav {
  display: flex;
  gap: 4px;
  background: var(--gray-100);
  border-radius: 28px;
  padding: 4px;
  margin-bottom: 28px;
  overflow-x: auto;
}
.tab-btn {
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 500;
  color: var(--gray-600);
  white-space: nowrap;
  transition: all var(--transition);
}
.tab-btn.active { background: var(--white); color: var(--teal); font-weight: 600; box-shadow: var(--shadow-sm); }
.tab-btn:hover:not(.active) { color: var(--charcoal); }

.articles-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.article-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.article-card-img {
  height: 180px;
  background: var(--teal-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.article-card-img i { font-size: 48px; color: var(--teal); opacity: 0.5; }
.article-card-body { padding: 16px 20px 20px; }
.article-card-category {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--teal);
  margin-bottom: 6px;
}
.article-card-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--charcoal);
  line-height: 1.4;
  margin-bottom: 8px;
}
.article-card-read {
  font-size: 13px;
  font-weight: 600;
  color: var(--teal);
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ── Trust Section ── */
.trust-section {
  background: var(--teal-bg);
  padding: 64px 0;
}
.trust-pillars {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.trust-pillar {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  text-align: center;
  transition: all var(--transition);
  border: 1px solid transparent;
}
.trust-pillar:hover { border-color: var(--teal-light); box-shadow: var(--shadow-md); }
.trust-pillar-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.trust-pillar-icon i { font-size: 26px; color: var(--teal); }
.trust-pillar h4 { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
.trust-pillar p { font-size: 13px; color: var(--gray-500); line-height: 1.5; }

/* ── Featured Programs ── */
.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.program-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
  background: var(--white);
}
.program-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.program-card-img {
  height: 140px;
  background: linear-gradient(135deg, var(--teal-light), var(--teal-bg));
  display: flex;
  align-items: center;
  justify-content: center;
}
.program-card-img i { font-size: 40px; color: var(--teal); opacity: 0.6; }
.program-card-body { padding: 16px 18px 18px; }
.program-card-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--coral);
  margin-bottom: 4px;
}
.program-card-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  line-height: 1.3;
}

/* ── Videos Section ── */
.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.video-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.video-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.video-card-thumb {
  height: 150px;
  background: var(--charcoal);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.video-card-thumb .play-btn {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(255,255,255,0.95);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.video-card:hover .play-btn { background: var(--coral); color: var(--white); }
.video-card-thumb .play-btn i { font-size: 22px; color: var(--charcoal); }
.video-card:hover .play-btn i { color: var(--white); }
.video-card-body { padding: 14px 16px 16px; }
.video-card-title {
