function showToast(message) {
  const toast = document.getElementById('toast');
  toast.textContent = message;
  toast.classList.add('show');
  setTimeout(() => toast.classList.remove('show'), 3000);
}

function handleNewsletterSubmit(e, formId) {
  e.preventDefault();
  const form = document.getElementById(formId);
  const email = form.querySelector('input[type="email"]').value;
  if (email) {
    showToast('Welcome aboard! Check your inbox for a confirmation.');
    form.reset();
  }
}

/* ── Mobile Nav Toggle (responsive) ── */
// Simple approach: hide mega-menus via CSS on mobile, maintain hover on desktop
document.querySelectorAll('.nav-link').forEach(link => {
  link.addEventListener('click', function(e) {
    if (window.innerWidth <= 1024) {
      e.preventDefault();
      const mega = this.parentElement.querySelector('.mega-menu');
      if (mega) {
        const isVisible = mega.style.opacity === '1';
        document.querySelectorAll('.mega-menu').forEach(m => { m.style.opacity = ''; m.style.visibility = ''; });
        if (!isVisible) {
          mega.style.opacity = '1';
          mega.style.visibility = 'visible';
          mega.style.transform = 'translateX(-50%) translateY(4px)';
        }
      }
    }
  });
});

// Close mobile menus on outside click
document.addEventListener('click', function(e) {
  if (window.innerWidth <= 1024 && !e.target.closest('.nav-item')) {
    document.querySelectorAll('.mega-menu').forEach(m => { m.style.opacity = ''; m.style.visibility = ''; });
  }
});
</script>
